"use client"

import type { ReactNode } from "react"

import { needsDecision, taskCost } from "@/lib/agent-task-board-model"
import type { TaskView, ThreadRef } from "@/lib/agent-task-types"
import { AcceptanceList } from "@/components/ui/acceptance-list"
import { agentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { AttemptTimeline } from "@/components/ui/attempt-timeline"
import { DependencyChips } from "@/components/ui/dependency-chips"
import { ProposalActions } from "@/components/ui/proposal-actions"
import { RelativeTime } from "@/components/ui/relative-time"
import { TaskStatusIcon, TaskStatusPill, taskStatusTones } from "@/components/ui/task-status"
import { proposalError, type TaskDisplayOptions } from "@/components/ui/task-card"
import { Block, DetailValue } from "@/components/ui/task-detail-parts"
import { UsageGrid } from "@/components/ui/usage-grid"

type TaskDetailContentProps = TaskDisplayOptions & {
  task: TaskView
  renderThreadLink?: (thread: ThreadRef) => ReactNode
  onOpenThread?: (thread: ThreadRef) => void
  /** Heading level of each section. */
  headingLevel?: number
}

function TaskDetailMeta({
  task,
  labels = agentTaskBoardLabels,
}: {
  task: TaskView
  labels?: TaskDisplayOptions["labels"]
}) {
  return (
    <div className="flex flex-wrap items-center gap-items text-xs">
      <span className="font-mono text-muted-foreground">{task.id}</span>
      <TaskStatusIcon status={task.status} />
      <TaskStatusPill status={task.status} labels={labels?.components.taskStatus} />
    </div>
  )
}

function TaskDetailContent({
  task,
  mode = "snapshot",
  now,
  locale,
  timeZone,
  formatCurrency,
  labels = agentTaskBoardLabels,
  onApproveProposal,
  onRejectProposal,
  agentApproval,
  onSelectTask,
  canSelect,
  renderThreadLink,
  onOpenThread,
  agentAvatars,
  headingLevel = 3,
}: TaskDetailContentProps) {
  const text = labels.panel
  const parts = labels.components
  const time = { now, locale, timeZone }
  const selectable = onSelectTask && task.dependsOn.some((dependency) => canSelect?.(dependency.id) ?? true)

  return (
    <>
      {task.goal && (
        <Block title={text.goal} level={headingLevel}>
          <p className="text-sm whitespace-pre-line">{task.goal}</p>
        </Block>
      )}

      {needsDecision(task) && (
        <Block title={text.decision} level={headingLevel}>
          {task.decisionNeeded && <p className="text-sm">{task.decisionNeeded}</p>}
          {task.status === "proposed" && (
            <ProposalActions
              taskId={task.id}
              mode={mode}
              onApprove={onApproveProposal}
              onReject={onRejectProposal}
              agentApproval={agentApproval}
              labels={labels.proposals}
              renderError={(error) => proposalError(error, labels)}
            />
          )}
        </Block>
      )}

      <div className="flex flex-col gap-x-section gap-y-group @2xl/task-detail:flex-row">
        <dl className="grid grid-cols-2 content-start gap-x-group gap-y-items text-sm @lg/task-detail:grid-cols-4 @2xl/task-detail:order-last @2xl/task-detail:w-64 @2xl/task-detail:shrink-0 @2xl/task-detail:grid-cols-2">
          {task.project && <DetailValue term={text.project}>{task.project}</DetailValue>}
          {task.profile && <DetailValue term={text.profile}>{task.profile}</DetailValue>}
          <DetailValue term={text.updated}>
            <RelativeTime value={task.updatedAt} {...time} />
          </DetailValue>
          <DetailValue
            term={text.cost}
            quantity={taskCost(task)}
            locale={locale}
            formatCurrency={formatCurrency}
            quantityLabels={parts.usage?.quantity}
          />
        </dl>

        <Block title={text.acceptance} level={headingLevel} className="min-w-0 flex-1">
          {task.acceptance.length > 0 ? (
            <AcceptanceList criteria={task.acceptance} labels={parts.acceptance} />
          ) : (
            <p className="text-sm text-muted-foreground">{text.noAcceptance}</p>
          )}
        </Block>
      </div>

      {task.dependsOn.length > 0 && (
        <Block title={text.dependencies} level={headingLevel}>
          <DependencyChips
            aria-label={text.dependenciesOf(task.id)}
            items={task.dependsOn.map((dependency) => ({
              id: dependency.id,
              label: `${dependency.id} ${dependency.title ?? ""}`.trim(),
              tone: taskStatusTones[dependency.status],
            }))}
            onSelect={selectable ? (id) => (canSelect?.(id) ?? true) && onSelectTask?.(id) : undefined}
          />
        </Block>
      )}

      {task.usage && (
        <Block title={text.usage} level={headingLevel}>
          <UsageGrid
            usage={task.usage}
            aria-label={text.usageOf(task.id)}
            labels={parts.usage}
            locale={locale}
            formatCurrency={formatCurrency}
          />
        </Block>
      )}

      <Block title={text.attempts} level={headingLevel}>
        {task.attempts.length > 0 ? (
          <AttemptTimeline
            attempts={task.attempts}
            labels={parts.attemptTimeline}
            usageLabels={parts.usage}
            usageOpenUpTo={1}
            agentAvatars={agentAvatars}
            formatCurrency={formatCurrency}
            renderThreadLink={renderThreadLink}
            onOpenThread={onOpenThread}
            {...time}
          />
        ) : (
          <p className="text-sm text-muted-foreground">{labels.empty.attempts}</p>
        )}
      </Block>
    </>
  )
}

export { TaskDetailContent, TaskDetailMeta }
export type { TaskDetailContentProps }

"use client"

import { useState, type ComponentProps } from "react"

import type { TaskView } from "@/lib/agent-task-types"
import { cn } from "@/lib/utils"
import { agentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { Dialog, DialogBackdrop, DialogClose, DialogContent, DialogTitle } from "@/components/ui/dialog"
import { Drawer, DrawerBackdrop, DrawerClose, DrawerContent, DrawerTitle } from "@/components/ui/drawer"
import { TaskStatusIcon, TaskStatusPill } from "@/components/ui/task-status"
import { TaskDetailContent, type TaskDetailContentProps } from "@/components/ui/task-detail-content"
import { CloseIcon } from "@/components/ui/task-detail-parts"
import type { CloseReason } from "@/components/ui/task-detail-panel"

type TaskDetailDialogProps = Omit<TaskDetailContentProps, "task" | "headingLevel"> & {
  /** The task to show; `undefined` closes the dialog. */
  task: TaskView | undefined
  presentation?: "dialog" | "drawer"
  /** Runs when a person or an agent closes it; clear the task to close it, or keep it to refuse. */
  onClose: (reason: CloseReason | "imperative") => void
  /** Where focus goes once it closes; the element focused before it opened by default. */
  finalFocus?: ComponentProps<typeof DialogContent>["finalFocus"]
  className?: string
}

const parts = {
  dialog: {
    Root: Dialog,
    Backdrop: DialogBackdrop,
    Content: DialogContent,
    Title: DialogTitle,
    Close: DialogClose,
  },
  drawer: {
    Root: Drawer,
    Backdrop: DrawerBackdrop,
    Content: DrawerContent,
    Title: DrawerTitle,
    Close: DrawerClose,
  },
}

const shapes = {
  dialog: "max-w-3xl gap-0 overflow-hidden p-0",
  drawer: "gap-0 overflow-hidden p-0 data-[side=right]:max-w-xl",
}

function closeReason(reason: string): CloseReason | "imperative" {
  return reason === "close-press" || reason === "escape-key" || reason === "outside-press" ? reason : "imperative"
}

function TaskDetailDialog({
  task,
  presentation = "dialog",
  onClose,
  finalFocus,
  className,
  labels = agentTaskBoardLabels,
  ...content
}: TaskDetailDialogProps) {
  // Keeps the last task on screen while the dialog animates out.
  const [shown, setShown] = useState(task)
  if (task && task !== shown) setShown(task)
  const current = task ?? shown
  const { Root, Backdrop, Content, Title, Close } = parts[presentation]

  return (
    <Root
      open={task !== undefined}
      onOpenChange={(open, details) => {
        if (!open) onClose(closeReason(details.reason))
      }}
      {...(presentation === "drawer" ? { side: "right" as const } : {})}
    >
      <Backdrop />
      <Content
        data-task-detail={presentation}
        data-task-id={current?.id}
        initialFocus="content"
        finalFocus={finalFocus}
        className={cn("@container/task-detail flex flex-col", shapes[presentation], className)}
      >
        {current && (
          <>
            <div className="flex shrink-0 items-start gap-items border-b px-inset-surface py-group">
              <div className="flex min-w-0 flex-1 flex-wrap items-center gap-inline">
                <Title data-slot="task-detail-title" className="text-base leading-snug">
                  <span className="font-mono text-muted-foreground">{current.id}</span> {current.title}
                </Title>
                <span className="inline-flex items-center gap-inline">
                  <TaskStatusIcon status={current.status} />
                  <TaskStatusPill status={current.status} labels={labels.components.taskStatus} />
                </span>
              </div>
              <Close variant="ghost" size="icon" aria-label={labels.panel.close}>
                <CloseIcon />
              </Close>
            </div>
            <div className="flex min-h-0 flex-1 flex-col gap-group overflow-y-auto overscroll-contain p-inset-surface">
              <TaskDetailContent task={current} labels={labels} {...content} headingLevel={3} />
            </div>
          </>
        )}
      </Content>
    </Root>
  )
}

export { TaskDetailDialog }
export type { TaskDetailDialogProps }

"use client"

import type { ReactNode } from "react"

import { formatQuantity, type Quantity, type QuantityLabels } from "@/lib/quantity"
import { cn } from "@/lib/utils"
import { QuantityValue } from "@/components/ui/quantity-value"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { usageFormatter } from "@/components/ui/usage"

type DetailValueProps = {
  term: string
  children?: ReactNode
  /** Shown instead of `children`; an estimate or a sourced value gets a tooltip saying so. */
  quantity?: Quantity
  locale?: string
  formatCurrency?: (usd: number) => string
  quantityLabels?: Partial<QuantityLabels>
}

function DetailValue({ term, children, quantity, locale, formatCurrency, quantityLabels }: DetailValueProps) {
  let value = children
  if (quantity) {
    const format = usageFormatter("cost", { locale, formatCurrency })
    const hint = formatQuantity(quantity, {
      format,
      locale,
      labels: quantityLabels,
    }).title
    const shown = (
      <QuantityValue value={quantity} format={format} locale={locale} labels={quantityLabels} title={undefined} />
    )
    value = hint ? (
      <Tooltip>
        <TooltipTrigger
          aria-label={`${term}: ${formatQuantity(quantity, { format, locale, labels: quantityLabels }).srText}`}
          className="cursor-help rounded-control underline decoration-dotted underline-offset-4 outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {shown}
        </TooltipTrigger>
        <TooltipContent>{hint}</TooltipContent>
      </Tooltip>
    ) : (
      shown
    )
  }
  return (
    <div data-slot="task-detail-value" className="flex min-w-0 flex-col gap-inline">
      <dt className="text-xs text-muted-foreground">{term}</dt>
      <dd className="min-w-0 truncate">{value}</dd>
    </div>
  )
}

// Escape inside a popup the panel holds (a reject confirmation, a tooltip) belongs to that popup.
function insidePopup(target: EventTarget, panel: Element) {
  const popup = target instanceof Element ? target.closest('[role="dialog"],[role="alertdialog"],[popover]') : null
  return popup !== null && popup !== panel && panel.contains(popup)
}

function Block({
  title,
  level,
  className,
  children,
}: {
  title: string
  level: number
  className?: string
  children: ReactNode
}) {
  const Heading = `h${Math.min(level, 6)}` as "h3"
  return (
    <section className={cn("flex flex-col gap-inline", className)}>
      <Heading className="text-xs font-medium tracking-wide text-muted-foreground uppercase">{title}</Heading>
      {children}
    </section>
  )
}

function CloseIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <path d="M18 6 6 18M6 6l12 12" />
    </svg>
  )
}

export { Block, CloseIcon, DetailValue, insidePopup }
export type { DetailValueProps }
